def match(pattern: str, text: str) -> bool:
    """
    Implements a recursive backtracking algorithm to perform regex matching 
    supporting literals, '.', '*', and '+'.
    """
    def is_match(p_idx: int, t_idx: int) -> bool:
        if p_idx == len(pattern) and t_idx == len(text):
            return True
        if p_idx < len(pattern) and pattern[p_idx] == '*':
            # Match '*' with zero of the preceding element
            return is_match(p_idx + 1, t_idx) or (t_idx < len(text) and is_match(p_idx, t_idx + 1))

        if p_idx < len(pattern) and pattern[p_idx] == '+':
            # Match '+' with one or more of the preceding element
            if t_idx < len(text) and (text[t_idx] == pattern[p_idx - 1] or pattern[p_idx - 1] == '.'):
                return is_match(p_idx, t_idx + 1)

        if p_idx < len(pattern) and t_idx < len(text) and (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.'):
            return is_match(p_idx + 1, t_idx + 1)

        return False

    return is_match(0, 0)

def match(pattern: str, text: str) -> bool:
    """
    Implements a dynamic programming approach to perform regex matching 
    supporting literals, '.', '*', and '+'.
    """
    m, n = len(pattern), len(text)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for i in range(1, m + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 2][0]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[i - 1] == text[j - 1] or pattern[i - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[i - 1] == '*':
                dp[i][j] = dp[i - 2][j] or (dp[i][j - 1] and (pattern[i - 2] == text[j - 1] or pattern[i - 2] == '.'))
            elif pattern[i - 1] == '+':
                dp[i][j] = (dp[i - 1][j - 1] and (pattern[i - 2] == text[j - 1] or pattern[i - 2] == '.')) or (j > 1 and dp[i][j - 1] and (pattern[i - 2] == text[j - 1] or pattern[i - 2] == '.'))

    return dp[m][n]

