    """
    Implements a recursive approach with memoization to perform regex matching 
    supporting literals, '.', '*', and '+'.
    """
    memo = {}

    def is_match(p_idx: int, t_idx: int) -> bool:
        if (p_idx, t_idx) in memo:
            return memo[(p_idx, t_idx)]

        if p_idx == len(pattern):
            return t_idx == len(text)

        first_match = t_idx < len(text) and (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.')

        if p_idx + 1 < len(pattern):
            if pattern[p_idx + 1] == '*':
                memo[(p_idx, t_idx)] = (is_match(p_idx + 2, t_idx) or 
                                        (first_match and is_match(p_idx, t_idx + 1)))
                return memo[(p_idx, t_idx)]
            elif pattern[p_idx + 1] == '+':
                memo[(p_idx, t_idx)] = (first_match and is_match(p_idx, t_idx + 1)) or \
                                       (first_match and t_idx + 1 < len(text) and pattern[p_idx] in 
                                        (text[t_idx], '.')) and is_match(p_idx, t_idx + 1)

        memo[(p_idx, t_idx)] = first_match and is_match(p_idx + 1, t_idx + 1)
        return memo[(p_idx, t_idx)]

    return is_match(0, 0)

def match(pattern: str, text: str) -> bool:
    """
    Implements an iterative dynamic programming approach to perform regex matching 
    supporting literals, '.', '*', and '+'.
    """
    dp = [[False] * (len(text) + 1) for _ in range(len(pattern) + 1)]
    dp[0][0] = True

    for p in range(1, len(pattern) + 1):
        if pattern[p - 1] == '*':
            dp[p][0] = dp[p - 2][0]

    for p in range(1, len(pattern) + 1):
        for t in range(1, len(text) + 1):
            if pattern[p - 1] == text[t - 1] or pattern[p - 1] == '.':
                dp[p][t] = dp[p - 1][t - 1]
            elif pattern[p - 1] == '*':
                dp[p][t] = dp[p - 2][t] or (dp[p][t - 1] and (pattern[p - 2] == text[t - 1] or pattern[p - 2] == '.'))
            elif pattern[p - 1] == '+':
                if p > 1 and (text[t - 1] == pattern[p - 2] or pattern[p - 2] == '.'):
                    dp[p][t] = dp[p][t - 1] or dp[p - 2][t - 1]

    return dp[len(pattern)][len(text)]

def match(pattern: str, text: str) -> bool:
    """
    Implements a recursive backtracking approach to perform regex matching 
    supporting literals, '.', '*', and '+'.
    """
    def backtrack(p_idx: int, t_idx: int) -> bool:
        if p_idx == len(pattern) and t_idx == len(text):
            return True
        if p_idx == len(pattern):
            return False

        first_match = (t_idx < len(text) and 
                       (text[t_idx] == pattern[p_idx] or pattern[p_idx] == '.'))

        if p_idx + 1 < len(pattern) and pattern[p_idx + 1] in '*+':
            if pattern[p_idx + 1] == '*':
                return (backtrack(p_idx + 2, t_idx) or
                        (first_match and backtrack(p_idx, t_idx + 1)))
            elif pattern[p_idx + 1] == '+':
                return (first_match and backtrack(p_idx, t_idx + 1))

        if first_match:
            return backtrack(p_idx + 1, t_idx + 1)

        return False

    return backtrack(0, 0)
